package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
public class RootBoundedWiringTest {
 private static String source(String name)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",name)).replace("\r\n","\n");}
 private static String between(String text,String first,String last){return text.substring(text.indexOf(first),text.indexOf(last,text.indexOf(first)));}
 @Test public void visibleIntentPrecedesRunAndOldModesAreExcluded()throws Exception{String a=source("DormantCaptureConfirmationActivity.java");String b=between(a,"private void confirmBounded()","void boundedFrameFinished");assertTrue(b.indexOf("boundedSpent=true")<b.indexOf("approveBounded"));assertTrue(b.indexOf("approveBounded")<b.indexOf("confirmedBounded"));assertTrue(b.contains("boundedIntent.sessionEnd()"));assertTrue(a.indexOf("if(RootBoundedBusinessScope.ACTIVE){\n   RootCaptureUi.boundedChoice")<a.indexOf("if(RootImageSeriesScope.ACTIVE){\n   RootCaptureUi.seriesChoice"));}
 @Test public void eachCandidateHasUniqueClaimWhileLogicalPhaseIsReservedOnce()throws Exception{String r=source("CaptureSessionRuntime.java");String b=between(r,"static CaptureSessionRuntime startBounded(","boolean isBounded()");assertTrue(b.contains("if(attempt==1)business.reserve(phase)"));assertTrue(b.contains("business.deadline(now)"));assertTrue(b.contains("issueBoundedFrame"));assertTrue(b.contains("EPOCH.retain(run)"));assertTrue(r.contains("RootBoundedBusinessScope.store(activity.getNoBackupFilesDir().toPath(),cardPhase,boundedAttempt)"));assertTrue(source("RootBoundedBusinessIntent.java").contains("deadline!=phaseEnds[i]"));}
 @Test public void candidateUsesBothAuditsAndSamePreparedHolder()throws Exception{String r=source("CaptureSessionRuntime.java");assertTrue(r.contains("MaaRecognizer.rootPreparedRewardCardAudit(activity.getApplicationContext(),preparedCapture)"));assertTrue(r.contains("preparedObservation=recognizer.preparedRewardCardObservation(result.owner())"));assertTrue(r.contains("preparedObservation.matches(preparedCapture)"));assertTrue(r.contains("preparedCapture.requestOwner()==requestOwner"));assertTrue(r.contains("BoundedCompletion(this,disposition)"));}
 @Test public void onlyExactHealthyUnpresentedCanContinue()throws Exception{String r=source("CaptureSessionRuntime.java");String b=between(r,"static boolean explicitUnpresented(","static BoundedCompletion.Disposition boundedDisposition");for(String condition:new String[]{"headerCount()!=0","nativeMoreCandidates()!=0","nativeWrongPageCandidates()!=0","marker.candidates()!=0","Status.NO_CARDS","cv.cardTotal()==0","band.populationVariance()==0.0","band.flatCount()==band.count()"})assertTrue(condition,b.contains(condition));assertTrue(r.contains("PngImageAudit.Status.MATCH"));assertTrue(r.contains("MaaImageBufferAudit.Status.VERIFIED_EQUAL"));}
 @Test public void rootSurvivesAdoptAndActionResourcesAreCheckedAgain()throws Exception{String b=between(source("CaptureSessionRuntime.java"),"private void closeBoundedOnOwner()","static final class BoundedCompletion");assertTrue(b.indexOf("acceptPreparedAfterCleanup")<b.indexOf("EPOCH.release(this)"));assertTrue(b.contains("rootResourcesClosed(result)&&autonomousRun.resourcesKnownClosed()"));assertTrue(b.contains("cancelled::get"));assertTrue(b.contains("if(released){if(rootEpochHeld)"));}
 @Test public void nextDoesNotRestoreOwnUiOrInventVisibleClick()throws Exception{String b=between(source("DormantCaptureConfirmationActivity.java"),"void boundedFrameFinished(","private volatile RootImageSeriesIntent");assertFalse(b.contains("new LiveClick"));assertFalse(b.contains("moveToFront"));assertTrue(b.contains("published"));assertTrue(b.contains("exact.commitBounded()"));assertTrue(b.contains("CaptureSessionRuntime.startBounded"));}
 @Test public void localTimeoutNeverGloballyCancelsSharedBoundedRun()throws Exception{String r=source("CaptureSessionRuntime.java");String b=between(r,"private void latchCancel()","void onActivityResult(");assertTrue(b.contains("if(autonomousRun!=null&&boundedIntent==null)autonomousRun.cancel()"));assertTrue(b.contains("autonomousRun.cancelPrepared(preparedCapture)"));assertFalse(b.contains("boundedIntent.cancel()"));}
 @Test public void nextNeedsActualClosedPriorAndAfterNeedsCommittedHistory()throws Exception{String r=source("CaptureSessionRuntime.java");String b=between(r,"static final class BoundedTransition","private void closeRootOnOwner()");assertTrue(b.contains("runtime.released&&runtime.reportFinal"));assertTrue(b.contains("runtime.boundedCommitted&&runtime.autonomousRun.returnReady()"));assertTrue(b.contains("runtime.boundedRetired"));assertTrue(b.contains("consumedSuccessfully"));assertTrue(b.contains("epoch.retaining()"));}
 @Test public void pureSourceGateAndNoAdditionalMetadataProbe()throws Exception{String r=source("CaptureSessionRuntime.java");assertFalse(r.contains(".seriesDiagnostics("));assertTrue(r.contains("rootPreflightMetadata.readPre("));assertTrue(r.contains("rootPreflightMetadata.readPost("));assertTrue(r.contains("boundedIntent.sourceMatches(result.ready())"));assertTrue(r.contains("rootPreflightBefore.sameSource(after.ready())"));}
 @Test public void fullTypedDiagnosticTraceIsRetainedAndNoDigestPrinted()throws Exception{String r=source("CaptureSessionRuntime.java");String b=between(r,"private void closeBoundedOnOwner()","static final class BoundedCompletion");assertTrue(b.contains("preparedObservation.diagnostic().summary()"));assertTrue(b.contains("seriesPngSummary(png)"));assertFalse(b.contains("Sha256("));String u=source("RootCaptureUi.java");assertTrue(u.contains("report.substring(start,Math.min(start+6500,report.length()))"));assertTrue(u.contains("最多6帧"));assertTrue(u.contains("00:55 至 02:30"));}
 @Test public void numberedChunksKeepEveryScalarAndNeverExceedTextLimit(){String text="phase=BEFORE attempt=1\n"+"safeScalar=true ".repeat(1200);var reports=java.util.Collections.nCopies(6,text);var chunks=RootCaptureUi.boundedDisplayChunks(reports);assertEquals(18,chunks.size());int total=0;for(int i=0;i<chunks.size();i++){String c=chunks.get(i);assertTrue(c.startsWith("boundedReport="+(i/3+1)+"/6 chunk="+(i%3+1)+"/3\n"));assertTrue(c.length()<7000);total+=c.length();}for(int i=0;i<6;i++){StringBuilder joined=new StringBuilder();for(int j=0;j<3;j++){String c=chunks.get(i*3+j);joined.append(c.substring(c.indexOf('\n')+1));}assertEquals(text,joined.toString());}System.out.println("BOUNDED_DISPLAY_SYNTHETIC_CHARS="+total+" chunks="+chunks.size());}
}
